<script lang="ts">
 import {onMount,tick} from 'svelte';import {replaceState} from '$app/navigation';import {page} from '$app/state';import {Button} from '$lib/components/ui/button';import {ArrowUp,ArrowDown,Volume2,VolumeX,Film,ArrowLeft} from '@lucide/svelte';import VideoPlayer from '../VideoPlayer.svelte';import VideoActions from './VideoActions.svelte';import AccessGate from './AccessGate.svelte';import {request} from '../api';import {appendUnique,adjacentIndex} from './feed-state';
 let {initialId='',user}:{initialId?:string;user:any}=$props();let items=$state<any[]>([]),cursor=$state(''),loading=$state(true),busy=$state(false),error=$state(''),index=$state(0),muted=$state(true),preferences=$state<any>({shorts_autoplay:true,reduce_motion:'system'}),actions=$state<any>(null),playerError=$state(''),retry=$state(0),overlayOpen=$state(false),container=$state<HTMLDivElement>();let alive=true,requestSequence=0;
 onMount(()=>{void initialize();return()=>{alive=false;requestSequence++;};});async function initialize(){try{if(user)preferences=await request('/settings/preferences').catch(()=>preferences);await load();if(initialId&&!items.some(v=>v.id===initialId)){const v=await request(`/videos/${initialId}`);if(v.format!=='short')throw new Error('This video is available in the standard watch view.');if(alive)items=appendUnique([v],items);}if(alive&&initialId){index=Math.max(0,items.findIndex(v=>v.id===initialId));await tick();scrollTo(index,false);}}catch(e){if(alive)error=(e as Error).message;}finally{if(alive)loading=false;}}
 async function load(){if(busy)return;busy=true;const sequence=++requestSequence;try{const result=await request(`/feed?${new URLSearchParams({format:'short',...(cursor?{cursor}:{})})}`);if(!alive||sequence!==requestSequence)return;items=appendUnique(items,result.items);cursor=result.next_cursor||'';}catch(e){if(alive)error=(e as Error).message;}finally{if(alive)busy=false;}}
 function scrollTo(target:number,smooth=true){const children=container?.querySelectorAll<HTMLElement>('.short-item');const reduced=preferences.reduce_motion==='reduce'||(preferences.reduce_motion==='system'&&matchMedia('(prefers-reduced-motion: reduce)').matches);if(children?.[target])container?.scrollTo({top:children[target].offsetTop,behavior:smooth&&!reduced?'smooth':'instant'});}
 function move(change:number){scrollTo(adjacentIndex(index,change,items.length));}
 $effect(()=>{if(!container||!items.length)return;const observer=new IntersectionObserver(entries=>{const candidate=entries.filter(e=>e.isIntersecting&&e.intersectionRatio>.65).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(candidate){const next=Number((candidate.target as HTMLElement).dataset.index);if(index!==next){index=next;actions=null;playerError='';retry=0;overlayOpen=false;}const id=items[next]?.id;if(id&&page.url.pathname!==`/shorts/${id}`)replaceState(`/shorts/${id}`,page.state);if(next>=items.length-3&&cursor&&!busy)void load();}},{root:container,threshold:[.65,.8]});container.querySelectorAll('.short-item').forEach(e=>observer.observe(e));return()=>observer.disconnect();});
 function keys(e:KeyboardEvent){if((e.target as HTMLElement).closest('input,textarea,button,select,video'))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();move(e.key==='ArrowDown'?1:-1);}}
</script>
<svelte:window onkeydown={keys}/>
<div class="shorts-title"><h1>Shorts</h1><a href="/discover"><ArrowLeft class="size-4"/>Back to videos</a></div>
{#if error}<div class="cloud-alert" role="alert">{error}<Button variant="ghost" onclick={()=>{error='';void load();}}>Try again</Button>{#if initialId}<a href={`/watch/${initialId}`}>Open watch view</a>{/if}</div>{/if}
{#if loading}<div class="shorts-loading" role="status">Loading Shorts…</div>{:else if !items.length}<div class="cloud-empty compact"><Film class="size-9"/><h2>No Shorts yet</h2><p>Published portrait videos will appear here.</p><Button variant="outline" href="/discover">Explore videos</Button></div>{:else}<div class="shorts-layout"><div class="shorts-scroll" bind:this={container} role="region" aria-label="Short videos. Use previous and next controls or scroll.">
{#each items as video,i(video.id)}<article class="short-item" data-index={i} aria-label={video.title} class:report-open={i===index&&overlayOpen}><div class="short-player">
{#if i===index}{#if actions?.access==='allowed'&&!playerError}{#key video.id+':'+retry}<VideoPlayer videoId={video.id} active={!overlayOpen} pauseWhenHidden={true} {muted} autoplay={preferences.shorts_autoplay&&!preferences.data_saving} captions={preferences.captions_enabled} dataSaving={preferences.data_saving} signedIn={!!user} onMutedChange={value=>muted=value} onerror={message=>playerError=message}/>{/key}{:else if actions?.access&&actions.access!=='allowed'}<AccessGate access={actions.access} returnTo={`/shorts/${video.id}`}/>{:else if playerError}<div class="short-feedback"><p>{playerError}</p><Button variant="outline" onclick={()=>{playerError='';retry++;}}>Retry playback</Button></div>{:else}<div class="short-feedback" role="status">Preparing video…</div>{/if}{:else}{#if video.thumbnail_url}<img src={video.thumbnail_url} alt="" loading="lazy"/>{:else}<Film class="size-8"/>{/if}{/if}</div>
{#if i===index}<div class="short-context"><div><a class="short-creator" href={`/channels/${video.handle}`}>@{video.handle}</a><h2>{video.title}</h2>{#if video.ai_generated}<p>AI-generated</p>{/if}</div><Button size="icon" variant="outline" aria-label={muted?'Turn sound on':'Mute video'} onclick={()=>muted=!muted}>{#if muted}<VolumeX class="size-4"/>{:else}<Volume2 class="size-4"/>{/if}</Button><VideoActions {video} {user} onAccess={v=>actions=v} onOverlayChange={open=>overlayOpen=open}/></div>{/if}</article>{/each}
{#if !cursor}<div class="shorts-end"><p>You're caught up.</p><a href="/discover">Explore more videos</a></div>{/if}</div><nav class="shorts-navigation" aria-label="Shorts navigation"><Button variant="outline" size="icon" aria-label="Previous Short" disabled={index===0} onclick={()=>move(-1)}><ArrowUp class="size-5"/></Button><span aria-live="polite">{index+1} of {items.length}</span><Button variant="outline" size="icon" aria-label="Next Short" disabled={index===items.length-1&&!cursor} onclick={()=>{if(index===items.length-1&&cursor)void load().then(()=>{void tick().then(()=>move(1));});else move(1);}}><ArrowDown class="size-5"/></Button></nav></div>{/if}
<style>.shorts-title{display:flex;align-items:center;justify-content:space-between;max-width:700px;margin:0 auto 18px}.shorts-title h1{font-size:22px;font-weight:600}.shorts-title>a{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted-foreground)}.shorts-layout{display:grid;grid-template-columns:minmax(0,440px) 60px;gap:24px;justify-content:center;height:calc(100dvh - 180px)}.shorts-scroll{overflow-y:auto;scroll-snap-type:y mandatory;position:relative;scrollbar-width:none;border-radius:12px}.shorts-scroll::-webkit-scrollbar{display:none}.short-item{position:relative;height:100%;scroll-snap-align:start;scroll-snap-stop:always;display:grid;grid-template-rows:minmax(0,1fr) auto;overflow:hidden;background:var(--background)}.short-item.report-open{overflow-y:auto;grid-template-rows:minmax(160px,1fr) auto}.short-player{min-height:0;display:flex;align-items:center;justify-content:center;background:#000;border-radius:10px;overflow:hidden}.short-player :global(video){width:100%;height:100%;object-fit:contain}.short-player img{width:100%;height:100%;object-fit:contain}.short-player :global(.access-gate){border-radius:0;min-height:100%;width:100%}.short-context{padding:14px 0 20px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px}.short-context>:global(.video-actions){grid-column:1/-1}.short-context>:global(.action-message){grid-column:1/-1;margin-top:0}.short-context>:global(.report-form){grid-column:1/-1}.short-context h2{font-size:14px;line-height:1.5;margin-top:6px;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.short-context p{font-size:11px;color:var(--muted-foreground);margin-top:5px}.short-creator{font-size:12px;font-weight:600}.shorts-navigation{display:flex;flex-direction:column;gap:14px;justify-content:center;align-items:center}.shorts-navigation span{font-size:11px;color:var(--muted-foreground);white-space:nowrap}.shorts-navigation :global(button){width:44px;height:44px}.shorts-end{text-align:center;padding:30px;font-size:13px;color:var(--muted-foreground);line-height:2}.shorts-end a{text-decoration:underline;text-underline-offset:4px}.short-feedback{display:grid;justify-items:center;gap:20px;padding:24px;color:white;text-align:center;font-size:13px}.shorts-loading{height:60vh;display:grid;place-content:center;color:var(--muted-foreground);font-size:13px}@media(max-width:600px){.shorts-layout{height:calc(100dvh - 220px);min-height:0;grid-template-columns:minmax(0,1fr) 36px;gap:10px}.shorts-navigation :global(button){width:36px;height:44px}.shorts-navigation span{font-size:10px}.shorts-title{margin-bottom:12px}.shorts-title h1{font-size:20px}.short-context h2{font-size:13px}.shorts-scroll{border-radius:8px}.short-context :global(button){padding-inline:8px;font-size:11px}.short-context :global(.video-actions){gap:5px}}
</style>
